#!/usr/bin/env python3
# Find the PLT stubs of imported functions in a 32-bit ARM ELF and write them as an assembler
# file: each function becomes an ARM-state function symbol at its stub address, so the linker
# turns calls from Thumb code into BLX (see build.sh).
#
# usage: plt_symbols.py <elf> <out.S> <function> [<function> ...]
import struct
import sys

R_ARM_JUMP_SLOT = 22


def sections(d):
    shoff, = struct.unpack_from("<I", d, 0x20)
    shentsize, shnum, shstrndx = struct.unpack_from("<HHH", d, 0x2e)
    hdr = [struct.unpack_from("<10I", d, shoff + i * shentsize) for i in range(shnum)]
    strtab = hdr[shstrndx]
    names = {}
    for h in hdr:
        o = strtab[4] + h[0]
        names[d[o:d.index(b"\0", o)].decode()] = h
    return names


def main(elf, out, funcs):
    d = open(elf, "rb").read()
    sec = sections(d)
    dynsym, dynstr = sec[".dynsym"], sec[".dynstr"]
    relplt, plt = sec[".rel.plt"], sec[".plt"]

    def symname(i):
        st_name = struct.unpack_from("<I", d, dynsym[4] + i * 16)[0]
        o = dynstr[4] + st_name
        return d[o:d.index(b"\0", o)].decode()

    got = {}
    for i in range(relplt[5] // 8):
        r_offset, r_info = struct.unpack_from("<II", d, relplt[4] + i * 8)
        if r_info & 0xff == R_ARM_JUMP_SLOT:
            got[symname(r_info >> 8)] = r_offset

    def rot(imm12):
        r, v = ((imm12 >> 8) & 0xf) * 2, imm12 & 0xff
        return ((v >> r) | (v << (32 - r))) & 0xffffffff if r else v

    # stubs: add ip, pc, #a ; add ip, ip, #b ; ldr pc, [ip, #c]!  (12 bytes each)
    stub = {}
    a = plt[3] + 20                       # after the 20-byte PLT0
    while a + 12 <= plt[3] + plt[5]:
        w = struct.unpack_from("<3I", d, a - plt[3] + plt[4])
        if w[0] & 0xfffff000 == 0xe28fc000 and w[1] & 0xfffff000 == 0xe28cc000:
            stub[a + 8 + rot(w[0] & 0xfff) + rot(w[1] & 0xfff) + (w[2] & 0xfff)] = a
            a += 12
        else:
            a += 4
    lines = ["@ generated by plt_symbols.py from %s" % elf.split("/")[-1], "    .arm"]
    for f in funcs:
        addr = stub[got[f]]
        lines += ["    .global %s" % f, "    .type %s, %%function" % f, "    .set %s, 0x%x" % (f, addr)]
    open(out, "w").write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2], sys.argv[3:])
